import sys

MOD = 998244353
A_BYTE = b'A'


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    T = int(next(it))
    out = []

    for _ in range(T):
        H = int(next(it))
        W = int(next(it))

        n = H + W
        parent = list(range(n))
        diff = [0] * n
        size = [1] * n
        comp = n
        ok = True

        def unite(x, y, w, parent=parent, diff=diff, size=size):
            rx = x
            px = 0
            while parent[rx] != rx:
                pr = parent[rx]
                g = parent[pr]
                if g != pr:
                    diff[rx] ^= diff[pr]
                    parent[rx] = g
                    px ^= diff[rx]
                    rx = g
                else:
                    px ^= diff[rx]
                    rx = pr

            ry = y
            py = 0
            while parent[ry] != ry:
                pr = parent[ry]
                g = parent[pr]
                if g != pr:
                    diff[ry] ^= diff[pr]
                    parent[ry] = g
                    py ^= diff[ry]
                    ry = g
                else:
                    py ^= diff[ry]
                    ry = pr

            if rx == ry:
                if (px ^ py) == w:
                    return 0
                return -1

            t = px ^ py ^ w
            if size[rx] < size[ry]:
                parent[rx] = ry
                diff[rx] = t
                size[ry] += size[rx]
            else:
                parent[ry] = rx
                diff[ry] = t
                size[rx] += size[ry]
            return 1

        col_s = [0] * W
        first_row = None
        cols = range(1, W)

        for i in range(H):
            row = next(it)

            if not ok:
                continue

            row_parity = row.count(A_BYTE) & 1
            if row_parity:
                ok = False
                continue

            a0 = row[0] & 1
            q_left = row_parity ^ a0

            if i == 0:
                first_row = row

                bit = a0
                if bit == 0:
                    res = unite(0, H, 1 ^ q_left)
                    if res < 0:
                        ok = False
                    elif res:
                        comp -= 1

                if ok:
                    q_left = 0
                    for j in cols:
                        bit = row[j] & 1
                        if bit == 0:
                            res = unite(0, H + j, 1 ^ q_left)
                            if res < 0:
                                ok = False
                                break
                            elif res:
                                comp -= 1
                        q_left ^= bit

            else:
                bit = a0
                col_s[0] ^= bit
                if bit == 0:
                    res = unite(i, H, 1 ^ q_left ^ col_s[0])
                    if res < 0:
                        ok = False
                    elif res:
                        comp -= 1

                if ok:
                    q_left = 0
                    for j in cols:
                        bit = row[j] & 1
                        col_s[j] ^= bit
                        if bit == 0:
                            res = unite(i, H + j, 1 ^ q_left ^ col_s[j])
                            if res < 0:
                                ok = False
                                break
                            elif res:
                                comp -= 1
                        q_left ^= bit

        if ok:
            for j, ch in enumerate(first_row):
                if (ch & 1) != col_s[j]:
                    ok = False
                    break

        if not ok:
            out.append("0")
        else:
            out.append(str(pow(2, comp, MOD)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if abs(k) > total:
            return -1

        offset = total
        target_bit = k + offset

        # DP for subsequences with positive product (no zeros).
        # dp_even: even length, dp_odd: odd length.
        # Mapping: product -> bitset of achievable alternating sums.
        dp_even = {}
        dp_odd = {}

        for x in nums:
            # A positive-product subsequence cannot contain 0,
            # and cannot contain x > limit because product only increases.
            if x == 0 or x > limit:
                continue

            new_even = dp_even.copy()
            new_odd = dp_odd.copy()

            # Start a new subsequence with x.
            bit = 1 << (offset + x)
            new_odd[x] = new_odd.get(x, 0) | bit

            # Append x to even-length subsequences: next sign is +.
            for p, bits in dp_even.items():
                np = p * x
                if np <= limit:
                    shifted = bits << x
                    if shifted:
                        new_odd[np] = new_odd.get(np, 0) | shifted

            # Append x to odd-length subsequences: next sign is -.
            for p, bits in dp_odd.items():
                np = p * x
                if np <= limit:
                    shifted = bits >> x
                    if shifted:
                        new_even[np] = new_even.get(np, 0) | shifted

            dp_even, dp_odd = new_even, new_odd

        # Best positive product, if any.
        for p in range(limit, 0, -1):
            bits = dp_even.get(p, 0) | dp_odd.get(p, 0)
            if (bits >> target_bit) & 1:
                return p

        # If no positive product works, check product 0 subsequences.
        # Such subsequences must contain at least one zero.
        if 0 not in nums:
            return -1

        # Feasibility DP for alternating sum k with at least one zero.
        # dp[used_zero][parity] -> bitset of achievable sums.
        dp = [[0, 0], [0, 0]]
        dp[0][0] = 1 << offset  # empty subsequence: used_zero=False, parity=0

        for x in nums:
            ndp = [[dp[0][0], dp[0][1]], [dp[1][0], dp[1][1]]]
            is_zero = (x == 0)

            for used in range(2):
                for parity in range(2):
                    bits = dp[used][parity]
                    if not bits:
                        continue

                    nused = used | (1 if is_zero else 0)
                    nparity = parity ^ 1

                    if parity == 0:
                        shifted = bits << x
                    else:
                        shifted = bits >> x

                    if shifted:
                        ndp[nused][nparity] |= shifted

            dp = ndp

        if ((dp[1][0] | dp[1][1]) >> target_bit) & 1:
            return 0

        return -1

