    to = [-1] * 26

    for s, t in zip(S, T):
        c = ord(s) - 97
        d = ord(t) - 97
        if to[c] == -1:
            to[c] = d
        elif to[c] != d:
            print(-1)
            return

    active = [False] * 26
    m = 0
    for i in range(26):
        if to[i] != -1:
            active[i] = True
            m += 1

    nonfixed = 0
    for i in range(26):
        if active[i] and to[i] != i:
            nonfixed += 1

    if nonfixed == 0:
        print(0)
        return

    if m == 26:
        seen = [False] * 26
        injective = True
        for i in range(26):
            d = to[i]
            if seen[d]:
                injective = False
                break
            seen[d] = True
        if injective:
            print(-1)
            return

    indeg = [0] * 26
    for i in range(26):
        if active[i]:
            d = to[i]
            if active[d]:
                indeg[d] += 1

    state = [0] * 26
    closed_cycles = 0

    for i in range(26):
        if not active[i] or state[i] != 0:
            continue

        path = []
        pos = {}
        cur = i

        while cur != -1 and active[cur] and state[cur] == 0:
            state[cur] = 1
            pos[cur] = len(path)
            path.append(cur)

            nxt = to[cur]
            if active[nxt]:
                cur = nxt
            else:
                cur = -1

        if cur != -1 and active[cur] and state[cur] == 1:
            start = pos[cur]
            cycle = path[start:]

            if len(cycle) > 1:
                closed = True
                for v in cycle:
                    if indeg[v] != 1:
                        closed = False
                        break
                if closed:
                    closed_cycles += 1

        for v in path:
            state[v] = 2

    print(nonfixed + closed_cycles)

