MAX_DIGITS = 10  # enough for r < 10^9, with one extra digit of safety
MAX_SUM = 9 * MAX_DIGITS


def _max_power_exp(p, limit):
    e = 0
    x = 1
    while x * p <= limit:
        x *= p
        e += 1
    return e


CAP2 = _max_power_exp(2, MAX_SUM)
CAP3 = _max_power_exp(3, MAX_SUM)
CAP5 = _max_power_exp(5, MAX_SUM)
CAP7 = _max_power_exp(7, MAX_SUM)

C2 = CAP2 + 1
C3 = CAP3 + 1
C5 = CAP5 + 1
C7 = CAP7 + 1
TOTAL = (MAX_SUM + 1) * C2 * C3 * C5 * C7


def _encode(s, e2, e3, e5, e7):
    return (((s * C2 + e2) * C3 + e3) * C5 + e5) * C7 + e7


EMPTY_IDX = _encode(0, 0, 0, 0, 0)

_DIGIT_EXP = [(0, 0, 0, 0) for _ in range(10)]
_DIGIT_EXP[2] = (1, 0, 0, 0)
_DIGIT_EXP[3] = (0, 1, 0, 0)
_DIGIT_EXP[4] = (2, 0, 0, 0)
_DIGIT_EXP[5] = (0, 0, 1, 0)
_DIGIT_EXP[6] = (1, 1, 0, 0)
_DIGIT_EXP[7] = (0, 0, 0, 1)
_DIGIT_EXP[8] = (3, 0, 0, 0)
_DIGIT_EXP[9] = (0, 2, 0, 0)

_REQ = [None] * (MAX_SUM + 1)
for s in range(1, MAX_SUM + 1):
    x = s
    r2 = r3 = r5 = r7 = 0

    while x % 2 == 0:
        r2 += 1
        x //= 2
    while x % 3 == 0:
        r3 += 1
        x //= 3
    while x % 5 == 0:
        r5 += 1
        x //= 5
    while x % 7 == 0:
        r7 += 1
        x //= 7

    if x == 1 and r2 <= CAP2 and r3 <= CAP3 and r5 <= CAP5 and r7 <= CAP7:
        _REQ[s] = (r2, r3, r5, r7)

_BEAUTIFUL = [False] * TOTAL
_NEXT = [-1] * (TOTAL * 9)

idx = 0
for s in range(MAX_SUM + 1):
    for e2 in range(C2):
        for e3 in range(C3):
            for e5 in range(C5):
                for e7 in range(C7):
                    if s > 0:
                        rq = _REQ[s]
                        if (
                            rq is not None
                            and e2 >= rq[0]
                            and e3 >= rq[1]
                            and e5 >= rq[2]
                            and e7 >= rq[3]
                        ):
                            _BEAUTIFUL[idx] = True

                    base = idx * 9
                    for d in range(1, 10):
                        ns = s + d
                        if ns <= MAX_SUM:
                            a2, a3, a5, a7 = _DIGIT_EXP[d]

                            ne2 = e2 + a2
                            if ne2 > CAP2:
                                ne2 = CAP2
                            ne3 = e3 + a3
                            if ne3 > CAP3:
                                ne3 = CAP3
                            ne5 = e5 + a5
                            if ne5 > CAP5:
                                ne5 = CAP5
                            ne7 = e7 + a7
                            if ne7 > CAP7:
                                ne7 = CAP7

                            _NEXT[base + d - 1] = _encode(ns, ne2, ne3, ne5, ne7)

                    idx += 1

_DP = [[0] * TOTAL for _ in range(MAX_DIGITS + 1)]
_DP[0] = [1 if b else 0 for b in _BEAUTIFUL]

for rem in range(1, MAX_DIGITS + 1):
    prev = _DP[rem - 1]
    curr = _DP[rem]
    nxt = _NEXT

    for i in range(TOTAL):
        base = i * 9
        total = 0
        for k in range(9):
            ni = nxt[base + k]
            if ni != -1:
