_POW9 = [1] * (MAX_DIGITS + 2)
for i in range(1, len(_POW9)):
    _POW9[i] = _POW9[i - 1] * 9


def _zero_free_count(n):
    if n <= 0:
        return 0

    digits = list(map(int, str(n)))
    length = len(digits)
    ans = 0

    for k in range(1, length):
        if k < len(_POW9):
            ans += _POW9[k]
        else:
            ans += 9 ** k

    for i, cur in enumerate(digits):
        rem = length - i - 1

        if cur > 1:
            if rem < len(_POW9):
                ans += (cur - 1) * _POW9[rem]
            else:
                ans += (cur - 1) * (9 ** rem)

        if cur == 0:
            break
    else:
        ans += 1

    return ans


def _zero_free_beautiful(n):
    if n <= 0:
        return 0

    digits = list(map(int, str(n)))
    length = len(digits)
    ans = 0

    max_short = min(length - 1, MAX_DIGITS)
    for k in range(1, max_short + 1):
        ans += _DP[k][EMPTY_IDX]

    state = EMPTY_IDX

    for i, cur in enumerate(digits):
        rem = length - i - 1

        for d in range(1, cur):
            ni = _NEXT[state * 9 + (d - 1)]
            if ni != -1:
                ans += _DP[rem][ni]

        if cur == 0:
            break

        ni = _NEXT[state * 9 + (cur - 1)]
        if ni == -1:
            break
        state = ni
    else:
        if _BEAUTIFUL[state]:
            ans += 1

    return ans


def _count_beautiful(n):
    if n <= 0:
        return 0

    # Every positive number containing digit 0 is beautiful.
    zero_containing = n - _zero_free_count(n)
    return zero_containing + _zero_free_beautiful(n)


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        if l > r:
            return 0
        return _count_beautiful(r) - _count_beautiful(l - 1)

from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k >= n:
            return [0] * n

        children = [None]
        cnt = [0]
        depth = [0]
        ends = [None]

        for i, w in enumerate(words):
            node = 0
            cnt[0] += 1
            for ch in w:
                d = children[node]
                if d is None:
                    d = {}
                    children[node] = d

                nxt = d.get(ch)
                if nxt is None:
                    nxt = len(children)
                    d[ch] = nxt
                    children.append(None)
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                    ends.append(None)

                node = nxt
                cnt[node] += 1

            lst = ends[node]
            if lst is None:
                ends[node] = [i]
            else:
                lst.append(i)

        N = len(children)
        first = [0] * N
        last = [0] * N
        word_pos = [0] * n
        pos = 0

        stack = [0]
        while stack:
            node = stack.pop()
            if node >= 0:
                first[node] = pos

                lst = ends[node]
                if lst is not None:
                    for idx in lst:
                        word_pos[idx] = pos
                        pos += 1

                stack.append(~node)
                d = children[node]
                if d is not None:
                    stack.extend(d.values())
            else:
                node = ~node
                last[node] = pos - 1

        children = None
        ends = None
        d = None
        lst = None

        end_max = [0] * n
        start_max = [0] * n
        always = 0

        for node in range(N):
            c = cnt[node]
            dep = depth[node]

            if c > k:
                if dep > always:
                    always = dep
            elif c == k:
                l = first[node]
                r = last[node]
                if l <= r:
                    if dep > end_max[r]:
                        end_max[r] = dep
                    if dep > start_max[l]:
                        start_max[l] = dep

        cnt = depth = first = last = None

        pref = [0] * (n + 1)
        for i in range(n):
            if end_max[i] > pref[i]:
                pref[i + 1] = end_max[i]
            else:
                pref[i + 1] = pref[i]

        suff = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            if start_max[i] > suff[i + 1]:
                suff[i] = start_max[i]
            else:
                suff[i] = suff[i + 1]

        end_max = start_max = None

        ans = [0] * n
        for i in range(n):
            p = word_pos[i]
            best = always

            if pref[p] > best:
                best = pref[p]
            if suff[p + 1] > best:
                best = suff[p + 1]

            ans[i] = best

        return ans

import sys
import math


def icbrt(n):
    lo, hi = 0, 1
    while hi * hi * hi <= n:
        hi *= 2
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


def main():
    data = sys.stdin.read().strip()
    if not data:
        return

    N = int(data)
    limit = icbrt(N)
    isqrt = math.isqrt

    for d in range(1, limit + 1):
        if N % d != 0:
            continue

        m = N // d

        # Let x = y + d.
        # N / d = 3y^2 + 3dy + d^2
        # 4(N/d) - d^2 = 3(2y + d)^2
        t = 4 * m - d * d
        if t % 3 != 0:
            continue

        k2 = t // 3
        k = isqrt(k2)
        if k * k != k2:
            continue

        if k <= d:
            continue
        if (k - d) % 2 != 0:
            continue

        y = (k - d) // 2
        x = y + d

        if x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)


if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # A[r] = maximum left endpoint a among pairs (a, r)
        # second[r] = second maximum left endpoint at r
        # cnt[r] = number of pairs attaining A[r]
        A = [0] * (n + 2)
        second = [0] * (n + 2)
        cnt = [0] * (n + 2)

        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a

            if a > A[b]:
                second[b] = A[b]
                A[b] = a
                cnt[b] = 1
            elif a == A[b]:
                cnt[b] += 1
            elif a > second[b]:
                second[b] = a

        # Prefix maximum of A, and the number of valid subarrays initially.
        pref = [0] * (n + 2)
        cur_max = 0
        valid = 0
        candidates = []

        for i in range(1, n + 1):
            x = A[i]
            if x > cur_max:
                # Only a unique strict prefix maximum can matter when removed.
                if cnt[i] == 1 and x > 0:
                    candidates.append(i)
                cur_max = x
            pref[i] = cur_max
            valid += i - cur_max

        if not candidates:
            return valid

        # next_ge[i] = first position j > i with A[j] >= A[i], or n + 1.
        next_ge = [n + 1] * (n + 2)
        stack = []
        for i in range(n, 0, -1):
            ai = A[i]
            while stack and A[stack[-1]] < ai:
                stack.pop()
            if stack:
                next_ge[i] = stack[-1]
            stack.append(i)

        # ps[i] = sum of prefix maxima starting from i to n,
        # following strict next-greater links.
        ps = [0] * (n + 2)
        stack = []
        for i in range(n, 0, -1):
            ai = A[i]
            while stack and A[stack[-1]] <= ai:
                stack.pop()
            nxt = stack[-1] if stack else n + 1
            ps[i] = ai * (nxt - i) + ps[nxt]
            stack.append(i)

        # Segment tree for range maximum and first position with value > threshold.
        size = 1
        while size < n:
            size <<= 1

        tree = [0] * (2 * size)
        for i in range(1, n + 1):
            tree[size + i - 1] = A[i]

        for i in range(size - 1, 0, -1):
            left = tree[i << 1]
            right = tree[(i << 1) | 1]
            tree[i] = left if left >= right else right

        def first_greater(l: int, threshold: int, tree=tree, size=size, n=n) -> int:
            """First 0-based index >= l with A[index] > threshold, or n if none."""
            if l >= n:
                return n
            l += size
            while True:
                while (l & 1) == 0:
                    l >>= 1
                if tree[l] > threshold:
                    while l < size:
                        l <<= 1
                        if tree[l] <= threshold:
                            l += 1
                    return l - size
                l += 1
                if (l & -l) == l:
                    break
            return n

        def range_max(l: int, r: int, tree=tree, size=size) -> int:
            """Maximum on 0-based half-open interval [l, r)."""
            res = 0
            l += size
            r += size
            while l < r:
                if l & 1:
                    v = tree[l]
                    if v > res:
                        res = v
                    l += 1
                if r & 1:
                    r -= 1
                    v = tree[r]
                    if v > res:
                        res = v
                l >>= 1
                r >>= 1
            return res

        max_drop = 0
        fg = first_greater
        rm = range_max

        for i in candidates:
            x = A[i]
            L = next_ge[i]
            base = pref[i - 1]
            if second[i] > base:
                base = second[i]

            length = L - i

            # 0-based search interval for positions strictly after i and before L:
            # [i, L - 1)
            l0 = i
            r0 = L - 1

            if l0 < r0:
                p0 = fg(l0, base)
                if p0 < r0:
                    t = p0 + 1  # 1-based first position after i with A[t] > base

                    if p0 == r0 - 1:
                        chain_sum = A[t] * (L - t)
                    else:
                        mx = rm(p0, r0)
                        c0 = fg(p0, mx - 1)
                        cur = c0 + 1  # first occurrence of the maximum in [t, L)
                        chain_sum = ps[t] - ps[cur] + A[cur] * (L - cur)

                    sum_new = base * (t - i) + chain_sum
                else:
                    sum_new = base * length
            else:
                sum_new = base * length

            drop = length * x - sum_new
            if drop > max_drop:
                max_drop = drop

        return valid + max_drop

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    adj = [[] for _ in range(N)]

    idx = 2
    for _ in range(M):
        x = data[idx] - 1
        y = data[idx + 1] - 1
        z = data[idx + 2]
        idx += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    dist = [-1] * N
    ans = [0] * N

    for s in range(N):
        if dist[s] != -1:
            continue

        if not adj[s]:
            dist[s] = 0
            ans[s] = 0
            continue

        dist[s] = 0
        stack = [s]
        comp = [s]
        max_d = 0

        while stack:
            v = stack.pop()
            dv = dist[v]

            for to, w in adj[v]:
                nd = dv ^ w
                if dist[to] == -1:
                    dist[to] = nd
                    if nd > max_d:
                        max_d = nd
                    stack.append(to)
                    comp.append(to)
                elif dist[to] != nd:
                    sys.stdout.write("-1\n")
                    return

        size = len(comp)
        bit_len = max_d.bit_length()
        c = 0

        if bit_len:
            counts = [0] * bit_len

            for v in comp:
                val = dist[v]
                b = 0
                while val:
                    if val & 1:
                        counts[b] += 1
                    val >>= 1
                    b += 1

            for b in range(bit_len):
                if counts[b] * 2 > size:
                    c |= 1 << b

        for v in comp:
            ans[v] = dist[v] ^ c

    sys.stdout.write(" ".join(map(str, ans)) + "\n")


