class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        p = [ord(ch) - 97 for ch in str2]

        # Apply all 'T' constraints.
        fixed = [-1] * L
        for i, flag in enumerate(str1):
            if flag == 'T':
                for pos, val in enumerate(p, i):
                    old = fixed[pos]
                    if old == -1:
                        fixed[pos] = val
                    elif old != val:
                        return ""

        # isF_end[pos] == 1 iff a forbidden window ends at pos.
        isF_end = bytearray(L)
        for i, flag in enumerate(str1):
            if flag == 'F':
                isF_end[i + m - 1] = 1

        # Prefix function for KMP.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and p[i] != p[j]:
                j = pi[j - 1]
            if p[i] == p[j]:
                j += 1
            pi[i] = j

        bits = [1 << i for i in range(m)]
        all_mask = (1 << m) - 1
        m1 = m - 1
        last_code = p[m1]
        bit_last = bits[m1]

        # KMP automaton, normalized so state is always 0..m-1.
        # trans_by_char[c][state] = next state after reading char c.
        trans_by_char = [[0] * m for _ in range(26)]
        pre_any = [0] * m  # pre_any[s]: states that can reach s with some char

        for state in range(m):
            bit_state = bits[state]
            for c in range(26):
                if c == p[state]:
                    nxt = state + 1
                elif state == 0:
                    nxt = 0
                else:
                    nxt = trans_by_char[c][pi[state - 1]]

                if nxt == m:
                    nxt = pi[m - 1]

                trans_by_char[c][state] = nxt
                pre_any[nxt] |= bit_state

        # For fast fixed-character backward DP.
        target_bits = [[bits[trans_by_char[c][q]] for q in range(m)] for c in range(26)]

        # For free positions, build byte-wise inverse-image tables:
        # table_free[chunk][byte] = states that can reach any next-state
        # represented by that byte using some character.
        chunks = (m + 7) // 8
        table_free = [[0] * 256 for _ in range(chunks)]

        lsb_index = [0] * 256
        for b in range(8):
            lsb_index[1 << b] = b

        for k in range(chunks):
            base = k * 8
            arr = table_free[k]
            for mask in range(1, 256):
                lsb = mask & -mask
                b = lsb_index[lsb]
                s = base + b
                prev = mask ^ lsb
                if s < m:
                    arr[mask] = arr[prev] | pre_any[s]
                else:
                    arr[mask] = arr[prev]

        # States reachable from state m-1 by a character different from last_code.
        next_from_last = [trans_by_char[c][m1] for c in range(26)]
        nonlast_next_mask = 0
        for c in range(26):
            if c != last_code:
                nonlast_next_mask |= bits[next_from_last[c]]

        # feasible[pos] is a bitmask of KMP states from which suffix pos..L-1
        # can be completed validly.
        feasible = [0] * (L + 1)
        feasible[L] = all_mask

        range_m = range(m)
        range_m1 = range(m - 1)

        for pos in range(L - 1, -1, -1):
            fn = feasible[pos + 1]
            if fn == 0:
                feasible[pos] = 0
                continue

            isF = isF_end[pos]
            fc = fixed[pos]

            if fc != -1:
                if fn == all_mask:
                    res = all_mask
                    if isF and fc == last_code:
                        res &= ~bit_last
                else:
                    tb = target_bits[fc]
                    res = 0
                    if isF and fc == last_code:
                        for q in range_m1:
                            if fn & tb[q]:
                                res |= bits[q]
                    else:
                        for q in range_m:
                            if fn & tb[q]:
                                res |= bits[q]
                feasible[pos] = res
            else:
                if fn == all_mask:
                    res = all_mask
                else:
                    res = 0
                    x = fn
                    k = 0
                    while x:
                        byte = x & 255
                        if byte:
                            res |= table_free[k][byte]
                        x >>= 8
                        k += 1

                    # At an 'F' end, state m-1 cannot use last_code.
                    if isF and (res & bit_last) and not (fn & nonlast_next_mask):
                        res &= ~bit_last

                feasible[pos] = res

        if not (feasible[0] & 1):
            return ""

        # Greedily construct the lexicographically smallest valid string.
        ans = []
        state = 0

        for pos in range(L):
            fc = fixed[pos]
            isF = isF_end[pos]
            chosen = -1

            if fc != -1:
                c = fc
                if not (isF and state == m1 and c == last_code):
                    nxt = trans_by_char[c][state]
                    if feasible[pos + 1] & bits[nxt]:
                        chosen = c
                        state = nxt
            else:
                for c in range(26):
                    if isF and state == m1 and c == last_code:
                        continue
                    nxt = trans_by_char[c][state]
                    if feasible[pos + 1] & bits[nxt]:
                        chosen = c
                        state = nxt
                        break

            if chosen == -1:
                return ""

            ans.append(chr(97 + chosen))

        return "".join(ans)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Any count larger than k can be capped; k + 1 is enough for comparisons.
        INF = k + 1

        def mul_cap(a: int, b: int) -> int:
            if a == 0 or b == 0:
                return 0
            if a > INF // b:
                return INF
            return a * b

        # Capped factorials.
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = mul_cap(fact[i - 1], i)

        # Number of valid completions with odd_left odd numbers and even_left even
        # numbers remaining, where the next number must have parity next_parity:
        # 1 = odd, 0 = even.
        def ways(odd_left: int, even_left: int, next_parity: int) -> int:
            if odd_left < 0 or even_left < 0:
                return 0

            length = odd_left + even_left

            if next_parity == 1:  # next is odd
                need_odd = (length + 1) // 2
                need_even = length // 2
            else:                 # next is even
                need_odd = length // 2
                need_even = (length + 1) // 2

            if odd_left != need_odd or even_left != need_even:
                return 0

            return mul_cap(fact[odd_left], fact[even_left])

        odd_total = (n + 1) // 2
        even_total = n // 2

        # Total valid permutations.
        total = mul_cap(fact[odd_total], fact[even_total])
        if n % 2 == 0:
            total = mul_cap(2, total)

        if total < k:
            return []

        used = [False] * (n + 1)
        ans = []

        odd_left, even_left = odd_total, even_total
        last_parity = -1  # -1 means no previous element yet.

        for _ in range(n):
            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x & 1
                if last_parity != -1 and parity == last_parity:
                    continue

                next_odd_left = odd_left - (1 if parity == 1 else 0)
                next_even_left = even_left - (1 if parity == 0 else 0)

                if next_odd_left < 0 or next_even_left < 0:
                    continue

                cnt = ways(next_odd_left, next_even_left, 1 - parity)

                if cnt == 0:
                    continue

                if k > cnt:
                    k -= cnt
                else:
                    ans.append(x)
                    used[x] = True
                    odd_left, even_left = next_odd_left, next_even_left
                    last_parity = parity
                    break
            else:
                return []

        return ans

