def parse(s: bytes):
    gaps = []
    pars = bytearray()
    cnt = 0
    first = 0
    prev = 0

    for i, ch in enumerate(s, 1):
        if ch == 49:  # ord('1')
            if cnt == 0:
                first = i
            else:
                gaps.append(i - prev)
                pars.append((prev - first) & 1)
            prev = i
            cnt += 1

    return cnt, first, prev, gaps, pars


def can_match(D, Ap, T, Tp, beta):
    m = len(T)
    if m == 0:
        return True

    h = 0
    Dloc = D
    Tloc = T
    Aploc = Ap
    Tploc = Tp

    for r in range(len(Dloc)):
        if h == m:
            break

        d = Dloc[r]
        t = Tloc[h]

        if d >= t:
            if d > t or ((Aploc[r] ^ Tploc[h]) == beta):
                h += 1

    return h == m


def solve():
    input = sys.stdin.buffer.readline
    line = input()
    if not line:
        return

    tc = int(line)
    out = []

    for _ in range(tc):
        N = int(input())
        A = input().strip()
        B = input().strip()

        if N == 1:
            out.append("0")
            continue

        K, a0, a_last, D, Ap = parse(A)
        M, b0, b_last, T, Tp = parse(B)

        if K < M or M == 0:
            out.append("-1")
            continue

        L = b0 - a0
        R = a_last - b_last
        P = L + R

        if P < 0:
            out.append("-1")
            continue

        base = L if L >= R else R
        if base < 0:
            base = 0

        if M == 1:
            out.append(str(base))
            continue

        q = P & 1
        if q == 0 or L >= R:
            alpha_opt = 0
        else:
            alpha_opt = 1

        if can_match(D, Ap, T, Tp, alpha_opt):
            out.append(str(base))
        elif can_match(D, Ap, T, Tp, 1 - alpha_opt):
            out.append(str(base + 1))
        else:
            out.append("-1")

    sys.stdout.write("\n".join(out))


