from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        C = 4 * S

        # Map each boundary point to its clockwise perimeter coordinate in [0, 4*side).
        per = []
        for x, y in points:
            if y == 0:
                per.append(x)
            elif x == S:
                per.append(S + y)
            elif y == S:
                per.append(3 * S - x)
            else:
                per.append(4 * S - y)

        per.sort()
        n = len(per)

        if k <= 1:
            return 0
        if k > n:
            return 0

        # For k >= 4, the answer is never larger than side.
        # For any d <= side, Manhattan distance < d iff circular perimeter distance < d.
        # So the problem becomes choosing k points on a circle with minimum circular gap >= d.
        arr = per + [p + C for p in per]
        m = 2 * n
        steps = k - 1
        step_range = range(steps)

        hi = min(S, C // k)

        def can(d: int) -> bool:
            if d == 0:
                return True
            if d * k > C:
                return False

            # nxt[i] = first index j > i with arr[j] >= arr[i] + d
            nxt = [m] * m
            j = 0
            a = arr
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = a[i] + d
                while j < m and a[j] < target:
                    j += 1
                nxt[i] = j

            limit = C - d

            # Try every point as the first chosen point in clockwise order.
            for i in range(n):
                idx = i
                for _ in step_range:
                    idx = nxt[idx]
                    if idx >= m:
                        break

                # Last chosen point must leave a circular gap of at least d back to i.
                if idx < m and a[idx] <= a[i] + limit:
                    return True

            return False

        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) >> 1
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

