class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')
        la, lb, lc = len(a), len(b), len(c)

        # Only "**" can match the empty substring.
        if la == 0 and lb == 0 and lc == 0:
            return 0

        # Literal parts must appear in order without overlapping.
        if la + lb + lc > n:
            return -1

        INF = n + 1

        def build_next(pat: str):
            """
            Returns nxt where nxt[i] is the smallest start index >= i
            where pat occurs in s, or INF if it does not occur.
            """
            m = len(pat)
            if m == 0:
                return list(range(n + 1))
            if m > n:
                return [INF] * (n + 1)

            # KMP prefix function
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            # Find all occurrences.
            occ = bytearray(n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    occ[i - m + 1] = 1
                    j = pi[j - 1]

            # Build next-occurrence array.
            nxt = [INF] * (n + 1)
            last = INF
            for i in range(n, -1, -1):
                if occ[i]:
                    last = i
                nxt[i] = last
            return nxt

        next_a = build_next(a) if la else None
        if next_a is not None and next_a[0] == INF:
            return -1

        next_b = build_next(b) if lb else None
        if next_b is not None and next_b[0] == INF:
            return -1

        next_c = build_next(c) if lc else None
        if next_c is not None and next_c[0] == INF:
            return -1

        ans = INF
        min_possible = la + lb + lc

        for l in range(n + 1):
            # If a is non-empty, l must be the start of an occurrence of a.
            if la and next_a[l] != l:
                continue

            pos = l + la

            if lb:
                b_start = next_b[pos]
                if b_start == INF:
                    continue
            else:
                b_start = pos

            pos2 = b_start + lb

            if lc:
                c_start = next_c[pos2]
                if c_start == INF:
                    continue
            else:
                c_start = pos2

            length = c_start + lc - l
            if length < ans:
                ans = length
                if ans == min_possible:
                    return ans

        return -1 if ans == INF else ans

