import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    W, H, L, R, D, U = data
    mod = MOD

    need_left = L > 0
    need_bottom = D > 0

    left_updates = U - D if need_left else 0
    bottom_updates = R - L if need_bottom else 0
    total_updates = left_updates + bottom_updates
    common_den = W - L + H - D + 2

    max_inv_needed = 1
    if left_updates:
        if U + 1 > max_inv_needed:
            max_inv_needed = U + 1
        if common_den > max_inv_needed:
            max_inv_needed = common_den
    if bottom_updates:
        if R + 1 > max_inv_needed:
            max_inv_needed = R + 1
        if common_den > max_inv_needed:
            max_inv_needed = common_den

    # Choose how to provide modular inverses for the O(length) loops.
    # If very few updates are needed but denominators are huge, use pow() on demand.
    if total_updates == 0:
        inv_mode = 0
    elif total_updates <= 20000 and max_inv_needed > 1000000:
        inv_mode = 1
    else:
        inv_mode = 2

    N = W + H + 4
    fact = [1] * (N + 1)

    if inv_mode == 2:
        inv = [0] * (max_inv_needed + 1)
        if max_inv_needed >= 1:
            inv[1] = 1
        limit = max_inv_needed
        if limit > N:
            limit = N
        for i in range(2, limit + 1):
            fact[i] = fact[i - 1] * i % mod
            inv[i] = mod - (mod // i) * inv[mod % i] % mod
        for i in range(limit + 1, N + 1):
            fact[i] = fact[i - 1] * i % mod
    else:
        for i in range(2, N + 1):
            fact[i] = fact[i - 1] * i % mod

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * pow(fact[k] * fact[n - k] % mod, mod - 2, mod) % mod

    # Sum of f0(x,y) over 0 <= x <= X, 0 <= y <= Y,
    # where f0(x,y) = number of monotone paths ending at (x,y) in a full grid.
    def full(X, Y):
        if X < 0 or Y < 0:
            return 0
        return (C(X + Y + 4, X + 2) - (X + 1) * (Y + 1) - X - Y - 4) % mod

    def rect(a1, a2, b1, b2):
        if a1 > a2 or b1 > b2:
            return 0
        return (
            full(a2, b2)
            - full(a1 - 1, b2)
            - full(a2, b1 - 1)
            + full(a1 - 1, b1 - 1)
        ) % mod

    # Total paths in the full grid.
    ans = full(W, H)

    # Invalid paths that start inside the forbidden rectangle.
    # By symmetry, paths starting at (x,y) and ending anywhere = f0(W-x, H-y).
    invalid = rect(W - R, W - L, H - U, H - D)

    init_left = C(L + D + 1, L) if need_left else 0
    init_bottom = C(L + D + 1, L + 1) if need_bottom else 0
    init_bin2 = C(common_den, W - L + 1) if (need_left or need_bottom) else 0

    fact = None

    if inv_mode == 1:
        den_set = set()
        if left_updates:
            den_set.update(range(D + 2, U + 2))
            den_set.update(range(common_den - left_updates + 1, common_den + 1))
        if bottom_updates:
            den_set.update(range(L + 2, R + 2))
            den_set.update(range(common_den - bottom_updates + 1, common_den + 1))
        inv = {d: pow(d, mod - 2, mod) for d in den_set}
        del den_set
    elif inv_mode == 0:
        inv = {}

    # Invalid paths whose first forbidden point is on the left side x=L.
    if need_left:
        bin1 = init_left
        bin2 = init_bin2
        num1 = L + D + 2
        den1 = D + 2
        num2 = H - D + 1
        den2 = common_den
        length = U - D + 1
        inv_list = inv

        for _ in range(length - 1):
            f1 = bin1 - 1
            if f1 < 0:
                f1 += mod
            f2 = bin2 - 1
            if f2 < 0:
                f2 += mod

            invalid += (f1 * f2) % mod
            if invalid >= mod:
                invalid -= mod

            bin1 = bin1 * num1 % mod * inv_list[den1] % mod
            bin2 = bin2 * num2 % mod * inv_list[den2] % mod

            num1 += 1
            den1 += 1
            num2 -= 1
            den2 -= 1

        f1 = bin1 - 1
        if f1 < 0:
            f1 += mod
        f2 = bin2 - 1
        if f2 < 0:
            f2 += mod
        invalid += (f1 * f2) % mod
        if invalid >= mod:
            invalid -= mod

    # Invalid paths whose first forbidden point is on the bottom side y=D.
    if need_bottom:
        bin1 = init_bottom
        bin2 = init_bin2
        num1 = L + D + 2
        den1 = L + 2
        num2 = W - L + 1
        den2 = common_den
        length = R - L + 1
        inv_list = inv

        for _ in range(length - 1):
            f1 = bin1 - 1
            if f1 < 0:
                f1 += mod
            f2 = bin2 - 1
            if f2 < 0:
                f2 += mod

            invalid += (f1 * f2) % mod
            if invalid >= mod:
                invalid -= mod

            bin1 = bin1 * num1 % mod * inv_list[den1] % mod
            bin2 = bin2 * num2 % mod * inv_list[den2] % mod

            num1 += 1
            den1 += 1
            num2 -= 1
            den2 -= 1

        f1 = bin1 - 1
        if f1 < 0:
            f1 += mod
        f2 = bin2 - 1
        if f2 < 0:
            f2 += mod
        invalid += (f1 * f2) % mod
        if invalid >= mod:
            invalid -= mod

    print((ans - invalid) % mod)


