        d = {}
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            d[p] = e
        fac[n] = d
    return fac


FAC = build_factor_cache()


def calc_prime_factor(p, exps, mod=MOD):
    g = 0
    total = 0
    for a in exps:
        g = gcd(g, a)
        total += a

    if g == 0:
        return 1

    if g > 1:
        exps = [a // g for a in exps]
        total //= g
        base = pow(p, g, mod)
    else:
        base = p

    T = total
    if T == 0:
        return 1

    powb = [1] * (T + 1)
    for i in range(1, T + 1):
        powb[i] = (powb[i - 1] * base) % mod

    # dp0: height > 0, zero has not appeared yet
    # dp1: zero has appeared at least once
    dp0 = powb.copy()
    dp0[0] = 0
    dp1 = [0] * (T + 1)
    dp1[0] = 1

    for a in exps:
        if a == 0:
            dp0 = [(v * w) % mod for v, w in zip(dp0, powb)]
            dp1 = [(v * w) % mod for v, w in zip(dp1, powb)]
            continue

        ndp0 = [0] * (T + 1)
        ndp1 = [0] * (T + 1)

        d0 = dp0
        d1 = dp1
        pb = powb
        TT = T
        aa = a
        ta = TT - aa

        # Heights that can only be reached from nh + aa.
        r1 = aa - 1
        if r1 > ta:
            r1 = ta

        for nh in range(r1 + 1):
            h = nh + aa
            w = pb[nh]
            s0 = d0[h]
            s1 = d1[h]
            if nh == 0:
                x = s0 + s1
                if x >= mod:
                    x -= mod
                ndp1[0] = x
            else:
                if s0:
                    ndp0[nh] = (s0 * w) % mod
                if s1:
                    ndp1[nh] = (s1 * w) % mod

        # Heights that can be reached from both nh - aa and nh + aa.
        start = aa
        end = ta
        if start <= end:
            for nh in range(start, end + 1):
                w = pb[nh]

                s0 = d0[nh - aa] + d0[nh + aa]
                if s0 >= mod:
                    s0 -= mod

                s1 = d1[nh - aa] + d1[nh + aa]
                if s1 >= mod:
                    s1 -= mod

                if s0:
                    ndp0[nh] = (s0 * w) % mod
                if s1:
                    ndp1[nh] = (s1 * w) % mod

        # Heights that can only be reached from nh - aa.
        start = aa
        tmp = ta + 1
        if tmp > start:
            start = tmp

        for nh in range(start, TT + 1):
            h = nh - aa
            w = pb[nh]
            s0 = d0[h]
            s1 = d1[h]
            if s0:
                ndp0[nh] = (s0 * w) % mod
            if s1:
                ndp1[nh] = (s1 * w) % mod

        dp0 = ndp0
        dp1 = ndp1

    return sum(dp1) % mod


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N - 1]

    present = set()
    for x in A:
        if x > 1:
            present.update(FAC[x])

    ans = 1
    for p in present:
        exps = [FAC[x].get(p, 0) for x in A]
        ans = (ans * calc_prime_factor(p, exps)) % MOD

    print(ans)


if __name__ == "__main__":
    solve()

import sys
from math import gcd

SPARSE_LIMIT = 2000


def parse_fallback(data: bytes):
    L = len(data)
    i = 0
    while i < L and data[i] <= 32:
        i += 1

    n = 0
    while i < L and data[i] > 32:
        n = n * 10 + (data[i] - 48)
        i += 1

    S = [0] * n
    idx = 0
    num = 0
    in_num = False

    for c in data[i:]:
        if c > 32:
            num = num * 10 + (c - 48)
            in_num = True
        elif in_num:
            if idx < n:
                S[idx] = num
            idx += 1
            num = 0
            in_num = False

    if in_num:
        if idx < n:
            S[idx] = num

    return n, S


def sparse_count(S):
    st = set(S)
    contains = st.__contains__

    evens = []
    odds = []
    for v in S:
        if v & 1:
            odds.append(v)
        else:
            evens.append(v)

    ans = 0
    for lst in (evens, odds):
        m = len(lst)
        for i in range(m):
            a = lst[i]
            for j in range(i + 1, m):
                if contains((a + lst[j]) >> 1):
                    ans += 1
    return ans


def build_buffer(S, min_idx, k, L, odd):
    arr = bytearray((k * L + 7) // 8)

    if odd:
        for v in S:
            if v & 1:
                bit = ((v >> 1) - min_idx) * k
                arr[bit >> 3] |= 1 << (bit & 7)
    else:
        for v in S:
            if not (v & 1):
                bit = ((v >> 1) - min_idx) * k
                arr[bit >> 3] |= 1 << (bit & 7)

    x = int.from_bytes(arr, "little")
    del arr

    p = x * x
    del x

    prod_bits = k * (2 * L - 1)
    buf = p.to_bytes((prod_bits + 7) // 8 + 4, "little")
    del p
    return buf


def solve_bigint(S):
    n = len(S)
    if n < 3:
        return 0

    if n <= SPARSE_LIMIT:
        return sparse_count(S)

    mn = min(S)
    mx = max(S)
    if n == mx - mn + 1:
        return ((n - 1) * (n - 1)) // 4

    # Normalize by common divisor and by the same-parity affine map.
    while True:
        cnt_e = cnt_o = 0
        min_e = 10**18
        max_e = -1
        min_o = 10**18
        max_o = -1
        min_val = 10**18
        max_val = -1
        g = 0

        for v in S:
            if g != 1:
                g = gcd(g, v)

            if v < min_val:
                min_val = v
            if v > max_val:
                max_val = v

            if v & 1:
                cnt_o += 1
                idx = v >> 1
                if idx < min_o:
                    min_o = idx
                if idx > max_o:
                    max_o = idx
            else:
                cnt_e += 1
                idx = v >> 1
                if idx < min_e:
                    min_e = idx
                if idx > max_e:
                    max_e = idx

        if g > 1:
            for i in range(n):
                S[i] //= g
            continue

        if max_val == 0:
            return 0

        if cnt_e == 0:
            for i in range(n):
                S[i] = (S[i] - 1) >> 1
            continue

        if cnt_o == 0:
            for i in range(n):
                S[i] >>= 1
            continue

        break

    if n == max_val - min_val + 1:
        return ((n - 1) * (n - 1)) // 4

    L_e = max_e - min_e + 1
    L_o = max_o - min_o + 1
    lim_e = 2 * L_e - 1
    lim_o = 2 * L_o - 1
    shift_e = min_e << 1
    shift_o = (min_o << 1) + 1

    cont_e = (cnt_e == L_e)
    cont_o = (cnt_o == L_o)

    # Both parity classes are contiguous: use the triangular formula directly.
    if cont_e and cont_o:
        ans = 0
        Le, le, she = L_e, lim_e, shift_e
        Lo, lo, sho = L_o, lim_o, shift_o

        for B in S:
            total = 0

            u = B - she
            if 0 <= u < le:
                if u < Le:
                    total += u + 1
                else:
                    total += le - u

            u = B - sho
            if 0 <= u < lo:
                if u < Lo:
                    total += u + 1
                else:
                    total += lo - u

            ans += (total - 1) >> 1

        return ans

    # Even class is contiguous; only odd class needs convolution.
    if cont_e:
        k_o = max(1, cnt_o.bit_length())
        buf_o = build_buffer(S, min_o, k_o, L_o, True)

        ans = 0
        Le, le, she = L_e, lim_e, shift_e
        bo, ko, lo, sho = buf_o, k_o, lim_o, shift_o
        mo = (1 << k_o) - 1

        for B in S:
            total = 0

            u = B - she
            if 0 <= u < le:
                if u < Le:
                    total += u + 1
                else:
                    total += le - u

            idx = B - sho
            if 0 <= idx < lo:
                bit = idx * ko
                byte = bit >> 3
                off = bit & 7
                val = bo[byte] | (bo[byte + 1] << 8) | (bo[byte + 2] << 16) | (bo[byte + 3] << 24)
                total += (val >> off) & mo

            ans += (total - 1) >> 1

        return ans

    # Odd class is contiguous; only even class needs convolution.
    if cont_o:
        k_e = max(1, cnt_e.bit_length())
        buf_e = build_buffer(S, min_e, k_e, L_e, False)

        ans = 0
        be, ke, le, she = buf_e, k_e, lim_e, shift_e
        me = (1 << k_e) - 1
        Lo, lo, sho = L_o, lim_o, shift_o

        for B in S:
            total = 0

            idx = B - she
            if 0 <= idx < le:
                bit = idx * ke
                byte = bit >> 3
                off = bit & 7
                val = be[byte] | (be[byte + 1] << 8) | (be[byte + 2] << 16) | (be[byte + 3] << 24)
                total += (val >> off) & me

            u = B - sho
            if 0 <= u < lo:
                if u < Lo:
                    total += u + 1
                else:
                    total += lo - u

            ans += (total - 1) >> 1

        return ans

    # General case: convolve both parity classes with big integers.
    k_e = max(1, cnt_e.bit_length())
    k_o = max(1, cnt_o.bit_length())

    buf_e = build_buffer(S, min_e, k_e, L_e, False)
    buf_o = build_buffer(S, min_o, k_o, L_o, True)

    ans = 0
    be, ke, le, she = buf_e, k_e, lim_e, shift_e
    bo, ko, lo, sho = buf_o, k_o, lim_o, shift_o
    me = (1 << k_e) - 1
    mo = (1 << k_o) - 1

    for B in S:
        total = 0

        idx = B - she
        if 0 <= idx < le:
            bit = idx * ke
            byte = bit >> 3
            off = bit & 7
            val = be[byte] | (be[byte + 1] << 8) | (be[byte + 2] << 16) | (be[byte + 3] << 24)
            total += (val >> off) & me

        idx = B - sho
        if 0 <= idx < lo:
            bit = idx * ko
            byte = bit >> 3
            off = bit & 7
            val = bo[byte] | (bo[byte + 1] << 8) | (bo[byte + 2] << 16) | (bo[byte + 3] << 24)
            total += (val >> off) & mo

        ans += (total - 1) >> 1

    return ans


def solve_numpy(data: bytes):
    import numpy as np

    arr = np.fromstring(data, dtype=np.int64, sep=" ")
    if arr.size == 0:
        return 0

    n = int(arr[0])
    if n < 3:
        return 0

    S = arr[1:1 + n]
    del arr

    if n <= SPARSE_LIMIT:
        return sparse_count(S.tolist())

    mn = int(S.min())
    mx = int(S.max())
    if n == mx - mn + 1:
        return ((n - 1) * (n - 1)) // 4

    # Normalize by common divisor and same-parity affine maps.
    for _ in range(60):
        odd = int(np.count_nonzero(S & 1))

        if odd == 0:
            S >>= 1
            continue

        if odd == n:
            S = (S - 1) >> 1
            continue

        g = int(np.gcd.reduce(S))
        if g > 1:
            S //= g
            continue

        break

    mn = int(S.min())
    mx = int(S.max())
    if n == mx - mn + 1:
        return ((n - 1) * (n - 1)) // 4

    max_val = mx
    L = 1 << (2 * max_val).bit_length()

    a = np.zeros(L, dtype=np.float64)
    a[S] = 1.0

    f = np.fft.rfft(a)
    f *= f
    conv = np.fft.irfft(f, n=L)

    idx = S * 2
    vals = np.rint(conv[idx]).astype(np.int64)
    vals = np.maximum(vals, 1)

    return int(((vals - 1) // 2).sum())


def main():
    data = sys.stdin.buffer.read()
    if not data:
        return

    try:
        ans = solve_numpy(data)
        print(ans)
        return
    except ImportError:
        pass
    except Exception:
        pass

    _, S = parse_fallback(data)
    print(solve_bigint(S))


if __name__ == "__main__":
    main()

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        from array import array

        vals = [ord(ch) - 97 for ch in caption]
        dist = [[abs(c - v) for c in range(26)] for v in range(26)]
        R = range(26)

        # pref[c][i] = cost to change caption[0:i] all to character c
        pref = [array('i', [0]) * (n + 1) for _ in R]
        cur = [0] * 26
        for idx, v in enumerate(vals, 1):
            dv = dist[v]
            for c in R:
                cur[c] += dv[c]
                pref[c][idx] = cur[c]

        INF = 10 ** 9

        # B[c][i] = minimum cost to finish suffix i..n-1
        # given that we already have a valid run of character c (length >= 3).
        B = [array('i', [0]) * (n + 1) for _ in R]

        # minVal[c] = min over k >= current i of D[k][c] + pref[c][k],
        # where D[k][c] is the cost when a run of c has just ended at k.
        minVal = [pref[c][n] for c in R]  # D[n][c] = 0

        for i in range(n - 1, -1, -1):
            ip3 = i + 3

            if ip3 <= n:
                best1 = INF
                best2 = INF
                best_char = -1

                # D[i][c] = min over d != c of cost(i, i+3, d) + B[d][i+3]
                for d in R:
                    pd = pref[d]
                    val = B[d][ip3] + pd[ip3] - pd[i]
                    if val < best1:
                        best2 = best1
                        best1 = val
                        best_char = d
                    elif val < best2:
                        best2 = val

                for c in R:
                    dp = best1 if c != best_char else best2
                    pc = pref[c]
                    pi = pc[i]

                    if dp < INF:
                        cand = dp + pi
                        if cand < minVal[c]:
                            minVal[c] = cand

                    B[c][i] = minVal[c] - pi
            else:
                for c in R:
                    pc = pref[c]
                    B[c][i] = minVal[c] - pc[i]

        # Minimum total cost: choose first 3 characters, then state B.
        total_cost = INF
        for d in R:
            cost = pref[d][3] + B[d][3]
            if cost < total_cost:
                total_cost = cost

        if total_cost >= INF:
            return ""

        # Greedily construct the lexicographically smallest optimal caption.
        ans = []
        spent = 0
        i = 0
        cur_char = -1
        length = 0  # capped at 3; 0 means no current run yet

        while i < n:
            v = vals[i]
            ni = i + 1
            chosen = -1
            chosen_cost = 0

            for x in R:
                if length == 0:
                    new_len = 1
                elif length < 3:
                    if x != cur_char:
                        continue
                    new_len = length + 1
                else:
                    new_len = 3 if x == cur_char else 1

                cost = dist[v][x]

                if new_len >= 3:
                    add = B[x][ni]
                else:
                    j = ni + (3 - new_len)
                    if j <= n:
                        add = pref[x][j] - pref[x][ni] + B[x][j]
                    else:
                        add = INF

                if spent + cost + add == total_cost:
                    chosen = x
                    chosen_cost = cost
                    break

            if chosen == -1:
                return ""

            ans.append(chr(chosen + 97))
            spent += chosen_cost

            if length == 0:
                cur_char = chosen
                length = 1
            elif length < 3:
                length += 1
            else:
                if chosen != cur_char:
                    cur_char = chosen
                    length = 1

            i += 1

        return "".join(ans)

import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]
    s = [ord(c) - 97 for c in S]

    states = 1 << N

    # fvals[mask][i] = LCS length of S[:i] and a string whose DP row is mask
    fvals = []
    for mask in range(states):
        arr = [0] * (N + 1)
        for i in range(1, N + 1):
            arr[i] = arr[i - 1] + ((mask >> (i - 1)) & 1)
        fvals.append(arr)

    # Precompute transitions, grouped by resulting state.
    trans = []
    for mask in range(states):
        old = fvals[mask]
        cnt = {}
        for ch in range(26):
            nxt = 0
            prev = 0
            for i in range(1, N + 1):
                v = prev
                if old[i] > v:
                    v = old[i]
                if s[i - 1] == ch and old[i - 1] + 1 > v:
                    v = old[i - 1] + 1

                if v > prev:
                    nxt |= 1 << (i - 1)
                prev = v

            cnt[nxt] = cnt.get(nxt, 0) + 1
        trans.append(list(cnt.items()))

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, val in enumerate(dp):
            if val:
                for nxt, c in trans[mask]:
                    ndp[nxt] += val * c

        for i in range(states):
            ndp[i] %= MOD
        dp = ndp

    pop = [0] * states
    for mask in range(1, states):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        ans[pop[mask]] = (ans[pop[mask]] + val) % MOD

    print(" ".join(map(str, ans)))

if __name__ == "__main__":
    main()

import sys
from bisect import bisect_left


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]
    items = [[], [], []]

    idx = 2
    for _ in range(N):
        v = data[idx] - 1
        a = data[idx + 1]
        c = data[idx + 2]
        idx += 3
        if c <= X and a > 0:
            items[v].append((c, -a))

    if not items[0] or not items[1] or not items[2]:
        print(0)
        return

    dps = []

    for v in range(3):
        lst = items[v]
        lst.sort()

        d = [0] * (X + 1)
        S = 0
        i = 0
        L = len(lst)

        while i < L:
            c = lst[i][0]
            limit = X // c
            vals = []
            cnt = 0

            while i < L and lst[i][0] == c:
                if cnt < limit:
                    vals.append(-lst[i][1])
                    cnt += 1
                i += 1

            if not vals:
                continue

            if S == 0:
                pref = [0]
                total = 0
                for a in vals:
                    total += a
                    pref.append(total)

                m = len(vals)
                for j in range(X + 1):
                    k = j // c
                    if k > m:
                        k = m
                    d[j] = pref[k]

                S = m * c
                if S > X:
                    S = X
            else:
                cc = c
                for a in vals:
                    S2 = S + cc
                    if S2 > X:
                        S2 = X

                    fill_len = S2 - S
                    old = d[S]
                    if fill_len and old:
                        if fill_len == 1:
                            d[S + 1] = old
                        else:
                            d[S + 1:S2 + 1] = [old] * fill_len

                    aa = a
                    for cap in range(S2, cc - 1, -1):
                        nv = d[cap - cc] + aa
                        if nv > d[cap]:
                            d[cap] = nv

                    S = S2

        best = 0
        for j in range(X + 1):
            val = d[j]
            if val < best:
                d[j] = best
            else:
                best = val

        dps.append(d)

    d0, d1, d2 = dps
    low = 0
    high = min(d0[X], d1[X], d2[X]) + 1
    bl = bisect_left

    while high - low > 1:
        mid = (low + high) // 2
        cost = bl(d0, mid) + bl(d1, mid) + bl(d2, mid)
        if cost <= X:
            low = mid
        else:
            high = mid

    print(low)


