    solve()

import sys


def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    mod = int(data[1])

    n = N // 2
    D = N * (N - 1) // 2
    # In any valid graph, vertex 1 has no edge to the other N/2-1 even-distance vertices.
    deg = D - (n - 1)

    # Binomial coefficients modulo mod.
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        C[i][0] = C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod

    choose_even_set = C[N - 1][n - 1] % mod

    n1 = n + 1
    S = n1
    SS = S * S
    L = S * SS

    tri = [k * (k - 1) // 2 for k in range(n1)]
    max_base = max(n, tri[n])

    offE = [0] * n1
    offO = [0] * n1
    for k in range(1, n1):
        offE[k] = k * S + k
        offO[k] = k * SS + k

    rem_comb = [()] * n1
    for k in range(1, n1):
        rem_comb[k] = tuple((rem, C[rem][k]) for rem in range(k, n1))

    base_e = [[0] * n1 for _ in range(n1)]
    for e in range(n1):
        for o in range(n1):
            base_e[e][o] = (e * S + o) * S

    range_even = [()] * n1
    range_odd = [()] * n1
    for i in range(n1):
        range_even[i] = tuple(range(1, i + 1))
        range_odd[i] = tuple(range(1, i + 1))

    rem_o = [n - o for o in range(n1)]
    rem_e = [n - e for e in range(n1)]

    infos = []
    for e in range(1, n1):
        for o in range(n1):
            base = base_e[e][o]
            infos.append((
                base,
                rem_o[o],
                rem_e[e],
                range_even[e],
                range_odd[o],
            ))
    infos = tuple(infos)

    full_base = base_e[n][n]
    full_idx = tuple(full_base + p for p in range(1, n1))
    start_idx = base_e[1][0] + 1

    def evaluate(x):
        MOD = mod
        N1 = n1
        MAXB = max_base
        TRI = tri
        OFFE = offE
        OFFO = offO
        REMCOMB = rem_comb
        INFOS = infos
        FULL = full_idx
        START = start_idx
        LL = L

        y = x + 1
        pow_y = [1] * (MAXB + 1)
        for i in range(1, MAXB + 1):
            pow_y[i] = (pow_y[i - 1] * y) % MOD

        # Transition weights for adding a layer of size k after a layer of size p.
        # F(p,k) = (1+x)^{C(k,2)} * ((1+x)^p - 1)^k
        We = [[[] for _ in range(N1)] for __ in range(N1)]
        Wo = [[[] for _ in range(N1)] for __ in range(N1)]

        RNG = range(1, N1)
        RNG0 = range(N1)

        for p in RNG:
            t = pow_y[p] - 1
            if t < 0:
                t += MOD
            if t == 0:
                continue

            tp = 1
            for k in RNG:
                tp = (tp * t) % MOD
                f = (pow_y[TRI[k]] * tp) % MOD
                if f:
                    off_e = OFFE[k]
                    off_o = OFFO[k]
                    for rem, comb in REMCOMB[k]:
                        w = (comb * f) % MOD
                        We[rem][p].append((off_e, w))
                        Wo[rem][p].append((off_o, w))

        for rem in RNG0:
            for p in RNG0:
                if We[rem][p]:
                    We[rem][p] = tuple(We[rem][p])
                else:
                    We[rem][p] = ()
                if Wo[rem][p]:
                    Wo[rem][p] = tuple(Wo[rem][p])
                else:
                    Wo[rem][p] = ()

        dp0 = [0] * LL  # last layer is even
        dp1 = [0] * LL  # last layer is odd
        dp0[START] = 1

        # Topological order: e increases, then o increases.
        for base, ro, re, even_ps, odd_ps in INFOS:
            if ro:
                We_ro = We[ro]
                for p in even_ps:
                    raw = dp0[base + p]
                    if raw:
                        if raw >= MOD:
                            raw %= MOD
                        if raw:
                            for off, w in We_ro[p]:
                                dp1[base + off] += raw * w

            if re and odd_ps:
                Wo_re = Wo[re]
                for p in odd_ps:
                    raw = dp1[base + p]
                    if raw:
                        if raw >= MOD:
                            raw %= MOD
                        if raw:
                            for off, w in Wo_re[p]:
                                dp0[base + off] += raw * w

        total = 0
        for idx in FULL:
            total += dp0[idx] + dp1[idx]
        return total % MOD

    # Evaluate the answer polynomial at x = 0, 1, ..., deg.
    vals = [0] * (deg + 1)
    for x in range(1, deg + 1):
        vals[x] = (evaluate(x) * choose_even_set) % mod

    # Interpolate from values at 0..deg using Newton forward differences.
    def interpolate(values):
        MOD = mod
        d = len(values) - 1
        diff = values[:]
        delta = [0] * (d + 1)

        for k in range(d + 1):
            delta[k] = diff[0]
            for i in range(d - k):
                diff[i] = (diff[i + 1] - diff[i]) % MOD

        inv = [0] * (d + 2)
        inv[1] = 1
        for i in range(2, d + 2):
            inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

        res = [0] * (d + 1)
        binom = [0] * (d + 1)
        binom[0] = 1

        for k in range(d + 1):
            coeff = delta[k]
            if coeff:
                for i in range(k + 1):
                    res[i] = (res[i] + coeff * binom[i]) % MOD

            if k < d:
                invk = inv[k + 1]
                binom[k + 1] = 0
                for i in range(k + 1, -1, -1):
                    val = 0
                    if i > 0:
                        val += binom[i - 1]
                    if i <= k:
                        val -= k * binom[i]
                    binom[i] = (val * invk) % MOD

        return res

    coeffs = interpolate(vals)

    ans = []
    for m in range(N - 1, D + 1):
        if m <= deg:
            ans.append(str(coeffs[m] % mod))
        else:
            ans.append("0")

    sys.stdout.write(" ".join(ans) + "\n")


if __name__ == "__main__":
    solve()

