from math import isqrt

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    p = data[2:2 + n]
    del data
    if not p:
        print(0)
        return
    p.sort()
    min_p = p[0]
    max_p = p[-1]

    high = 2 * isqrt(m * min_p) + 2 * min_p + 1

    def feasible(x, ps=p, m=m, max_p=max_p):
        total = 0
        if x >= max_p:
            for pi in ps:
                c = (x // pi + 1) >> 1
                total += c * c * pi
                if total > m:
                    return False
            return True
        else:
            for pi in ps:
                if pi > x:
                    break
                c = (x // pi + 1) >> 1
                total += c * c * pi
                if total > m:
                    return False
            return True

    while feasible(high):
        high *= 2

    low = 0
    while high - low > 1:
        mid = (low + high) >> 1
        if feasible(mid):
            low = mid
        else:
            high = mid

    x = low
    count = 0
    cost = 0
    for pi in p:
        if pi > x:
            break
        c = (x // pi + 1) >> 1
        count += c
        cost += c * c * pi

    ans = count + (m - cost) // (x + 1)
    print(ans)

