MOD = 10**9 + 7

_fact = [1]
_invfact = [1]


def _ensure_fact(n: int) -> None:
    cur = len(_fact) - 1
    if n <= cur:
        return

    _fact.extend([1] * (n - cur))
    for i in range(cur + 1, n + 1):
        _fact[i] = _fact[i - 1] * i % MOD

    _invfact.extend([1] * (n - cur))
    _invfact[n] = pow(_fact[n], MOD - 2, MOD)
    for i in range(n, cur, -1):
        _invfact[i - 1] = _invfact[i] * i % MOD


class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        gaps = n - 1
        if k < 0 or k > gaps:
            return 0

        _ensure_fact(gaps)

        comb = _fact[gaps] * _invfact[k] % MOD * _invfact[gaps - k] % MOD
        return comb * (m % MOD) % MOD * pow((m - 1) % MOD, gaps - k, MOD) % MOD

