class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 0:
            return 0

        # Lengths of maximal blocks of identical characters in the original string.
        runs = []
        cnt = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                cnt += 1
            else:
                runs.append(cnt)
                cnt = 1
        runs.append(cnt)

        # Cost to make the whole string alternating, which is exactly the cost
        # needed when the target longest run length is 1.
        mismatches = 0
        for i, ch in enumerate(s):
            expected = '0' if i % 2 == 0 else '1'
            if ch != expected:
                mismatches += 1
        alt_cost = min(mismatches, n - mismatches)

        def can(limit: int) -> bool:
            if limit == 1:
                return alt_cost <= numOps

            # For limit >= 2, each original run of length L needs
            # floor(L / (limit + 1)) flips, and this is always sufficient.
            ops = 0
            block = limit + 1
            for length in runs:
                ops += length // block
                if ops > numOps:
                    return False
            return True

        lo, hi = 1, max(runs)
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

import sys
from bisect import bisect_right


def merge_dict(d):
    for k in list(d):
        intervals = d[k]
        if not intervals:
            d[k] = None
            continue

        if len(intervals) == 1:
            l, r = intervals[0]
            d[k] = [l, r]
            continue

        intervals.sort()
        starts = []
        ends = []
        cur_l, cur_r = intervals[0]

        for i in range(1, len(intervals)):
            l, r = intervals[i]
            if l <= cur_r:
                if r > cur_r:
                    cur_r = r
            else:
                starts.append(cur_l)
                ends.append(cur_r)
                cur_l, cur_r = l, r

        starts.append(cur_l)
        ends.append(cur_r)

        if len(starts) == 1:
            d[k] = [starts[0], ends[0]]
        else:
            d[k] = (starts, ends)


def covered(d, key, val, br=bisect_right):
    se = d.get(key)
    if se is None:
        return False

    # Single interval: [l, r]
    if type(se) is list:
        return se[0] <= val <= se[1]

    # Multiple intervals: (starts, ends)
    starts, ends = se
    idx = br(starts, val) - 1
    return idx >= 0 and ends[idx] >= val


def main():
    input = sys.stdin.buffer.readline

    N, M, Sx, Sy = map(int, input().split())

    xs = [0] * N
    ys = [0] * N
    for i in range(N):
        x, y = map(int, input().split())
        xs[i] = x
        ys[i] = y

    horizontal = {}
    vertical = {}

    cx, cy = Sx, Sy

    for _ in range(M):
        d, c_str = input().split()
        c = int(c_str)

        if d == b'U':
            ny = cy + c
            lst = vertical.get(cx)
            if lst is None:
                vertical[cx] = [(cy, ny)]
            else:
                lst.append((cy, ny))
            cy = ny

        elif d == b'D':
            ny = cy - c
            lst = vertical.get(cx)
            if lst is None:
                vertical[cx] = [(ny, cy)]
            else:
                lst.append((ny, cy))
            cy = ny

        elif d == b'R':
            nx = cx + c
            lst = horizontal.get(cy)
            if lst is None:
                horizontal[cy] = [(cx, nx)]
            else:
                lst.append((cx, nx))
            cx = nx

        else:  # L
            nx = cx - c
            lst = horizontal.get(cy)
            if lst is None:
                horizontal[cy] = [(nx, cx)]
            else:
                lst.append((nx, cx))
            cx = nx

    merge_dict(horizontal)
    merge_dict(vertical)

    ans = 0
    cov = covered

    for i in range(N):
        px = xs[i]
        py = ys[i]
        if cov(horizontal, py, px) or cov(vertical, px, py):
            ans += 1

    print(cx, cy, ans)


