import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n + 1)]

    for i in range(1, len(data), 2):
        u = data[i]
        v = data[i + 1]
        adj[u].append(v)
        adj[v].append(u)

    del data

    deg = [len(a) for a in adj]

    best = 0
    target = n - 1

    for c in range(1, n + 1):
        neigh = adj[c]
        l = len(neigh)

        if l == 1:
            d = deg[neigh[0]]
            if d >= 2 and d > best:
                best = d

        elif l == 2:
            d0 = deg[neigh[0]]
            d1 = deg[neigh[1]]

            if d0 >= 2:
                if d1 >= 2:
                    if d0 < d1:
                        d0, d1 = d1, d0
                    if d0 > best:
                        best = d0
                    val = d1 * 2
                    if val > best:
                        best = val
                elif d0 > best:
                    best = d0
            elif d1 >= 2 and d1 > best:
                best = d1

        elif l > 2:
            arr = []
            for v in neigh:
                d = deg[v]
                if d >= 2:
                    arr.append(d)

            la = len(arr)

            if la == 1:
                d = arr[0]
                if d > best:
                    best = d

            elif la == 2:
                d0 = arr[0]
                d1 = arr[1]
                if d0 < d1:
                    d0, d1 = d1, d0
                if d0 > best:
                    best = d0
                val = d1 * 2
                if val > best:
                    best = val

            elif la > 2:
                arr.sort(reverse=True)
                for i, d in enumerate(arr, 1):
                    val = d * i
                    if val > best:
                        best = val

        if best >= target:
            best = target
            break

    ans = n - best - 1
    if ans < 0:
        ans = 0

    sys.stdout.write(str(ans) + "\n")


