from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold

        active = []
        has_one = False
        for x in nums:
            if x <= T:
                active.append(x)
                if x == 1:
                    has_one = True

        isolated = len(nums) - len(active)

        if not active:
            return isolated

        # If 1 is present, every active value is directly connected to it.
        if has_one:
            return isolated + 1

        if len(active) == 1:
            return isolated + 1

        active.sort()

        parent = list(range(T + 1))
        size = [1] * (T + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> bool:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return False
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
            return True

        # rep[m] is the first active divisor of m that has been processed.
        rep = [0] * (T + 1)

        # For each current x, avoid repeatedly unioning with the same rep value.
        seen = [0] * (T + 1)
        stamp = 0

        components = len(active)

        for x in active:
            stamp += 1
            for m in range(x, T + 1, x):
                r = rep[m]
                if r == 0:
                    rep[m] = x
                elif seen[r] != stamp:
                    seen[r] = stamp
                    if union(x, r):
                        components -= 1

        return isolated + components
